ALTER TABLE document_control.analysis_records DROP CONSTRAINT analysis_records_kind_check;
ALTER TABLE document_control.analysis_records ADD CONSTRAINT analysis_records_kind_check CHECK(kind IN ('PEST','SWOT','RISK'));
DO $category$ DECLARE constraint_name text; BEGIN
  FOR constraint_name IN SELECT conname FROM pg_constraint WHERE conrelid='document_control.analysis_records'::regclass AND contype='c' AND pg_get_constraintdef(oid) LIKE '%category%'
  LOOP EXECUTE format('ALTER TABLE document_control.analysis_records DROP CONSTRAINT %I',constraint_name); END LOOP;
END $category$;
ALTER TABLE document_control.analysis_records ADD CONSTRAINT analysis_records_category_check CHECK(
  (kind='PEST' AND category IN ('Political','Economic','Social','Technological')) OR
  (kind='SWOT' AND category IN ('Strength','Weakness','Opportunity','Threat')) OR
  (kind='RISK' AND category IN ('Process','Product / Quality','Customer','Supplier','People','Equipment','Safety / Compliance','Business continuity','Other')));
ALTER TABLE document_control.analysis_records ADD COLUMN risk_assessment jsonb CHECK(risk_assessment IS NULL OR jsonb_typeof(risk_assessment)='object'),
  ADD COLUMN risk_review jsonb CHECK(risk_review IS NULL OR jsonb_typeof(risk_review)='object'),
  ADD COLUMN risk_state text NOT NULL DEFAULT 'Active' CHECK(risk_state IN ('Active','Retired'));
UPDATE identity.permissions SET name=replace(name,'PEST and SWOT','ISO'),description=description || ' Includes Risk-Based Thinking assessment, treatment and ongoing monitoring.' WHERE key LIKE 'iso.analysis.%';

